// n8n Code node: JavaScript, Run Once for All Items.
const fields = [
  'boardToken', 'jobId', 'companyName', 'title', 'location', 'departments',
  'firstPublished', 'updatedAt', 'jobUrl', 'descriptionText', 'signalId',
];

function spreadsheetCell(value) {
  const text = Array.isArray(value)
    ? value.map(String).join('; ')
    : value == null ? '' : String(value);
  const visible = text.replace(/^[\s\uFEFF]+/, '');
  return /^[=+\-@＝＋－＠]/.test(visible) || /^[\t\r\n]/.test(text)
    ? "'" + text
    : text;
}

return $input.all().map((item, index) => {
  const row = item.json;
  if (!row || typeof row.jobUrl !== 'string' || typeof row.title !== 'string'
      || !['string', 'number'].includes(typeof row.jobId)) {
    throw new Error('Expected a Greenhouse job dataset row. Check the HTTP response and keep full-response mode off.');
  }
  return {
    json: Object.fromEntries(fields.map(field => [field, spreadsheetCell(row[field])])),
    pairedItem: { item: index },
  };
});
